The user wants me to create index.js in bench-todo that implements a command `node index.js add "<文本>"` which appends todo text to todos.json in the same directory (JSON array, elements with id and text fields).

Let me first read the existing package.json (it exists). Then create index.js.

Let me think about the implementation:
- Parse process.argv
- Expect first arg "add" and second arg the text
- Read todos.json in same directory (using import.meta.dirname or path.dirname(fileURLToPath(import.meta.url)))
- If not exists, start with empty array
- Generate id (e.g., Date.now() or increment based on max id)
- Append { id, text }
- Write back to todos.json with JSON.stringify

Need to handle Node version — import.meta.dirname available in Node 20.11+. Safer to use fileURLToPath. But keep it simple. Since type: module, use ES modules.

Let me write robust code:

```js
#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const todosPath = path.join(__dirname, 'todos.json');

async function main() {
  const [command, ...rest] = process.argv.slice(2);
  if (command !== 'add' || rest.length === 0) {
    console.error('Usage: node index.js add "<文本>"');
    process.exitCode = 1;
    return;
  }
  const text = rest.join(' ');
  let todos = [];
  try {
    const content = await readFile(todosPath, 'utf8');
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed)) todos = parsed;
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }
  const nextId = todos.reduce((max, t) => Math.max(max, Number(t.id) || 0), 0) + 1;
  todos.push({ id: nextId, text });
  await writeFile(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Added: ${text}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});
```

