#!/usr/bin/env node
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const todosPath = path.join(__dirname, 'todos.json');

async function main() {
  const [command, ...rest] = process.argv.slice(2);

  if (command !== 'add' || rest.length === 0) {
    console.error('Usage: node index.js add "<text>"');
    process.exitCode = 1;
    return;
  }

  const text = rest.join(' ');

  let todos = [];
  try {
    const content = await readFile(todosPath, 'utf8');
    const parsed = JSON.parse(content);
    if (Array.isArray(parsed)) {
      todos = parsed;
    }
  } catch (err) {
    if (err.code !== 'ENOENT') {
      throw err;
    }
  }

  const nextId = todos.reduce((max, todo) => Math.max(max, Number(todo.id) || 0), 0) + 1;
  todos.push({ id: nextId, text });

  await writeFile(todosPath, JSON.stringify(todos, null, 2) + '\n', 'utf8');
  console.log(`Added todo #${nextId}: ${text}`);
}

main().catch((err) => {
  console.error(err);
  process.exitCode = 1;
});

