import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const indexJs = path.join(__dirname, 'index.js');
const todosPath = path.join(__dirname, 'todos.json');

const fixture = {
  version: 1,
  todos: [
    { id: 1, text: '旧任务', priority: 'normal', createdAt: '2020-01-01T00:00:00.000Z' },
    { id: 2, text: '新任务', priority: 'high', createdAt: '2021-01-01T00:00:00.000Z' },
  ],
};

const reset = () => writeFileSync(todosPath, JSON.stringify(fixture, null, 2) + '\n');
const read = () => JSON.parse(readFileSync(todosPath, 'utf8'));
const run = (args) => execFileSync(process.execPath, [indexJs, ...args], {
  cwd: __dirname,
  encoding: 'utf8',
});

const original = readFileSync(todosPath, 'utf8');

try {
  reset();
  const out = run(['add', '买牛奶', '--priority', 'high']);
  const data = read();
  const added = data.todos.find((todo) => todo.id === 3);
  assert.match(out, /Added todo #3: 买牛奶 \[high\]/);
  assert.equal(data.todos.length, 3);
  assert.equal(added.text, '买牛奶');
  assert.equal(added.priority, 'high');
  assert.ok(added.createdAt);
  console.log('ok - add');

  reset();
  const lines = run(['list']).trim().split('\n');
  assert.deepEqual(lines, ['1. 新任务', '2. 旧任务']);
  console.log('ok - list');

  reset();
  run(['done', '1']);
  assert.equal(read().todos.find((todo) => todo.id === 1).done, true);
  console.log('ok - done');

  reset();
  run(['rm', '2']);
  const afterRm = read();
  assert.equal(afterRm.todos.length, 1);
  assert.equal(afterRm.todos.some((todo) => todo.id === 2), false);
  console.log('ok - rm');

  reset();
  run(['done', '1']);
  const clearOut = run(['clear']);
  const afterClear = read();
  assert.match(clearOut, /Cleared 1 done todo\(s\)/);
  assert.equal(afterClear.todos.length, 1);
  assert.equal(afterClear.todos[0].id, 2);
  console.log('ok - clear');
} finally {
  writeFileSync(todosPath, original);
}

